public partial class PanelWindow {
 int NaxxUiHand(MatchEngine g,string card,int seat=0){int id=970000+g.Players.Sum(p=>p.Hand.Count)+g.Graveyard.Count;while(g.Players.Any(p=>p.Hand.Any(h=>h.Id==id)))id++;g.Players[seat].Hand.Add(new HandCard{Id=id,CardId=card,Generated=true});return id;}
 public void PreviewNaxxScope(string folder){previewRun=true;Directory.CreateDirectory(folder);int before=checks;Check(NaxxRules.CardIds.Concat(NaxxRules.RemainingIds).All(id=>matchRules.Supports(catalog.Card(id))),"All thirty Naxx cards enabled in builder");if(VerificationRun.Network)VerifyNaxxTcp(folder);if(VerificationRun.Visual)PreviewRemainingNaxx(folder);File.WriteAllText(Path.Combine(folder,"naxx-verification.txt"),"PASS: "+(checks-before)+" assertions; WPF="+VerificationRun.Visual+"; loopback TCP="+VerificationRun.Network+"; Loatheb costs, secret privacy, Scientist/Duplicate, Avenge, Deathlord, Baron/Kelthuzad and Echo/Weblord; native healing/Redemption timing; seven-slot WPF when enabled. No two-computer test.");}
 void PreviewRemainingNaxx(string folder){LeaveLan();localTest=true;ApplyTheme(true,true);ApplyMode(false);SetEffectsLevel(EffectLevel.Low);match=MatchFixture();foreach(var p in match.Players){p.Board.Clear();p.Hand.Clear();}matchViewSeat=0;awaitHandoff=false;foreach(string id in new[]{"FP1_031","FP1_013","FP1_012","FP1_007","FP1_005","FP1_028","FP1_017"})match.Summon(0,id);foreach(string id in new[]{"FP1_014","FP1_015","FP1_008","FP1_027","FP1_001","FP1_024","FP1_029"})match.Summon(1,id);ShowPage("match");RenderMatch();UpdateLayout();Check(match.Players[0].Board.Count==7&&match.Players[1].Board.Count==7,"Full Naxx boards fit seven slots on both sides");Render(Path.Combine(folder,"naxx-complete-normal.png"));ApplyMode(true);RenderMatch();UpdateLayout();Check(matchEffectsCanvas.Visibility==System.Windows.Visibility.Collapsed,"Completed Naxx cards preserve silent minimal mode");Render(Path.Combine(folder,"naxx-complete-minimal.png"));ApplyMode(false);localTest=false;}
 void VerifyNaxxTcp(string folder){LeaveLan();ApplyTheme(true,true);ApplyMode(false);SetEffectsLevel(EffectLevel.Off);var guest=new PanelWindow(true){ShowInTaskbar=false,Opacity=0};guest.Show();guest.ApplyTheme(true,true);guest.ApplyMode(false);guest.SetEffectsLevel(EffectLevel.Low);try{
  lanPort.Text=FreeLanPort().ToString();lanDeck.SelectedIndex=0;lanClass.SelectedItem=Classes.First(c=>c.Key=="MAGE");BeginLan(true);guest.lanDeck.SelectedIndex=0;guest.lanClass.SelectedItem=Classes.First(c=>c.Key=="MAGE");guest.lanAddress.Text="127.0.0.1:"+lanPort.Text;guest.BeginLan(false);PumpLan(()=>lanReady&&guest.lanReady,"Naxx TCP peers connect");DoMatch("mulligan",selectedIds:new int[0]);PumpLan(()=>guest.match.Players[0].MulliganDone,"Naxx host mulligan synchronized");guest.DoMatch("mulligan",selectedIds:new int[0]);PumpLan(()=>match.MulliganComplete&&!guest.lanWaiting,"Naxx both mulligans complete");var g=lanAuthority.Game;foreach(var p in g.Players){p.Hand.Clear();p.Board.Clear();p.Mana=p.MaxMana=10;}
  int loatheb=NaxxUiHand(g,"FP1_030"),fire=NaxxUiHand(g,"VAN_CS2_029",1);PublishLan();BeginCard(loatheb);ClickEmptySlot(0,0);PumpLan(()=>guest.match.Players[1].SpellCostPenalty==5,"Loatheb public cost modifier reaches guest");Check(guest.match.HandCost(1,guest.match.Players[1].Hand.Single(h=>h.Id==fire))==9,"Guest UI shows nine-mana Fireball");DoMatch("end");PumpLan(()=>guest.match.Active==1,"Naxx guest turn");guest.BeginCard(fire);guest.ClickMatchTarget(new MatchTarget(0));PumpLan(()=>!guest.lanWaiting&&g.Players[0].Health==24,"Guest pays increased cost and resolves targeted spell");Check(g.Players[1].Mana==1,"Host deducts nine mana");guest.DoMatch("end");PumpLan(()=>!guest.lanWaiting&&guest.match.Active==0,"Naxx host turn restored");Check(guest.match.CardCost(1,catalog.Card("VAN_CS2_029"))==4,"Loatheb cost expiry reaches guest");
  foreach(var p in g.Players){p.Hand.Clear();p.Board.Clear();p.Mana=10;}g.Players[0].Deck.Clear();g.Players[0].Deck.Add("FP1_018");var scientist=g.Summon(0,"FP1_004");var yeti=g.Summon(0,"VAN_CS2_182");fire=NaxxUiHand(g,"VAN_CS2_029",1);PublishLan();DoMatch("end");PumpLan(()=>guest.match.Active==1&&guest.match.Players[1].Hand.Any(h=>h.Id==fire),"Scientist scenario reaches guest");guest.BeginCard(fire);guest.ClickMatchTarget(new MatchTarget(0,scientist.Id));PumpLan(()=>!guest.lanWaiting&&guest.match.Players[0].SecretCount==1,"Scientist secret count synchronizes");Check(g.Players[0].Hand.Count==0&&guest.match.Players[0].Hand.Count==0,"Fetched Duplicate does not trigger on Scientist's own death");string wire=JsonData.Serializer().Serialize(LanProtocol.View(g,1,"naxx-private",1));Check(!wire.Contains("FP1_018"),"Fetched secret identity stays off wire");g.Players[1].Mana=10;fire=NaxxUiHand(g,"VAN_CS2_029",1);PublishLan();PumpLan(()=>guest.match.Players[1].Hand.Any(h=>h.Id==fire),"Second guest Fireball received");guest.BeginCard(fire);guest.ClickMatchTarget(new MatchTarget(0,yeti.Id));PumpLan(()=>!guest.lanWaiting&&guest.match.Players[0].SecretCount==0&&guest.match.Players[0].HandCount==2,"Duplicate result reaches both views");Check(g.Players[0].Hand.Count==2&&guest.match.Players[0].Hand.Count==0,"Duplicate copies privately reach owner only");
  guest.DoMatch("end");PumpLan(()=>!guest.lanWaiting&&g.Active==0,"Avenge host turn");foreach(var p in g.Players){p.Board.Clear();p.Hand.Clear();p.Mana=10;}g.DestroySecrets(0);int avenge=NaxxUiHand(g,"FP1_020");var lord=g.Summon(0,"FP1_009");lord.DamageTaken=2;var ally=g.Summon(0,"VAN_CS2_231");g.Players[1].Deck.Clear();g.Players[1].Deck.AddRange(new[]{"VAN_CS2_029","VAN_EX1_319"});fire=NaxxUiHand(g,"VAN_CS2_029",1);PublishLan();BeginCard(avenge);PumpLan(()=>guest.match.Players[0].SecretCount==1,"Avenge anonymous count reaches guest");DoMatch("end");PumpLan(()=>guest.match.Active==1&&guest.match.Players[1].Hand.Any(h=>h.Id==fire),"Avenge guest turn");guest.BeginCard(fire);guest.ClickMatchTarget(new MatchTarget(0,lord.Id));PumpLan(()=>!guest.lanWaiting&&guest.match.Players[0].Board.Any(u=>u.Id==ally.Id&&u.BuffAttack==3)&&guest.match.Players[1].Board.Any(u=>u.CardId=="VAN_EX1_319"),"Avenge buff and Deathlord summon synchronize");Check(g.Players[1].Health==30,"Deathlord does not execute Flame Imp battlecry");Render(Path.Combine(folder,"naxx-avenge-deathlord.png"));

  foreach(var p in g.Players){p.Board.Clear();p.Hand.Clear();p.Mana=10;}g.Turn+=2;g.Active=1;g.DestroySecrets(0);var baron=g.Summon(0,"FP1_031");var egg=g.Summon(0,"FP1_007");fire=NaxxUiHand(g,"VAN_CS2_029",1);PublishLan();PumpLan(()=>guest.match.Players[1].Hand.Any(h=>h.Id==fire),"Remaining Naxx fixture reaches guest");guest.BeginCard(fire);guest.ClickMatchTarget(new MatchTarget(0,egg.Id));PumpLan(()=>!guest.lanWaiting&&guest.match.Players[0].Board.Count(u=>u.CardId=="FP1_007t")==2,"Baron doubled Egg deathrattle reaches guest");g.Summon(0,"FP1_013");PublishLan();guest.DoMatch("end");PumpLan(()=>!guest.lanWaiting&&guest.match.Active==0&&guest.match.Players[0].Board.Any(u=>u.CardId=="FP1_007"),"Kelthuzad resurrection at enemy end synchronizes");Check(guest.match.Players[0].Board.Select(u=>u.Id).Distinct().Count()==guest.match.Players[0].Board.Count,"Revived units keep unique public identities");Render(Path.Combine(folder,"naxx-baron-kelthuzad.png"));
  foreach(var p in g.Players){p.Board.Clear();p.Hand.Clear();p.Mana=10;}g.Summon(1,"FP1_017");int ooze=NaxxUiHand(g,"FP1_003"),drake=NaxxUiHand(g,"VAN_EX1_284",1);PublishLan();BeginCard(ooze);ClickEmptySlot(0,0);PumpLan(()=>guest.match.Players[0].Board.Any(u=>u.CardId=="FP1_003"),"Echo battlecry state reaches guest");var echo=g.Players[0].Board.Single();g.Buff(new MatchTarget(0,echo.Id),3,2);PublishLan();DoMatch("end");PumpLan(()=>guest.match.Active==1&&guest.match.Players[0].Board.Count(u=>u.CardId=="FP1_003")==2,"Buffed Echo copy reaches both clients");Check(guest.match.Players[0].Board.All(u=>u.BuffAttack==3&&u.BuffHealth==2),"Echo copied enchantments synchronize");Check(guest.match.HandCost(1,guest.match.Players[1].Hand.Single(h=>h.Id==drake))==7,"Weblord cost aura matches guest view");
  foreach(var p in g.Players){p.Board.Clear();p.Hand.Clear();p.Mana=10;p.Health=30;}g.Active=0;g.Turn+=2;g.DestroySecrets(0);g.DestroySecrets(1);g.Players[1].Health=20;g.Summon(0,"VAN_EX1_591");g.Summon(0,"FP1_001");int seeds=NaxxUiHand(g,"FP1_019");PublishLan();BeginCard(seeds);PumpLan(()=>guest.match.Players[1].Health==25&&guest.match.Players[0].Board.All(u=>u.CardId=="VAN_EX1_tk9"),"Native Chow healing after Soulpriest death synchronizes");Check(g.Players[1].Health==25,"Host also resolves native healing without stale spell conversion");
  foreach(var p in g.Players){p.Board.Clear();p.Hand.Clear();p.Mana=10;p.Health=30;}g.Active=1;g.Turn++;var redeemTarget=g.Summon(0,"VAN_CS2_182");g.Equip(0,"VAN_EX1_366");g.ArmSecret(0,new HandCard{Id=970900,CardId="VAN_EX1_136"});fire=NaxxUiHand(g,"VAN_CS2_029",1);PublishLan();PumpLan(()=>guest.match.Active==1&&guest.match.Players[1].Hand.Any(h=>h.Id==fire),"Redemption and Sword scenario reaches guest");guest.BeginCard(fire);guest.ClickMatchTarget(new MatchTarget(0,redeemTarget.Id));PumpLan(()=>!guest.lanWaiting&&guest.match.Players[0].Board.Count==1&&guest.match.Players[0].Board[0].Id!=redeemTarget.Id,"Redemption resurrection reaches guest");Check(g.Players[0].Board.Single().Health==2&&guest.match.Players[0].Board.Single().Health==2,"Redemption before Sword buff gives identical two-health minion on both peers");Check(guest.match.Players[0].WeaponDurability==4&&guest.match.Players[0].SecretCount==0,"Secret consumed and Sword durability synchronized");Render(Path.Combine(folder,"naxx-redemption-sword.png"));

 }finally{guest.LeaveLan();guest.Close();LeaveLan();}}
}
